from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub()
LeftDrive = Motor(Port.E, Direction.COUNTERCLOCKWISE)
RightDrive = Motor(Port.A, Direction.CLOCKWISE)
DriveBase1 = DriveBase(LeftDrive, RightDrive, 68.8, 25.4 * 4.375)
attachment = Motor(Port.B, Direction.CLOCKWISE)
color = ColorSensor(Port.C)


# The main program starts here.
DriveBase1.use_gyro(True)
print('Hello, Pybricks!')
attachment.run_angle(500, -430)
DriveBase1.straight(-300)
DriveBase1.turn(-45)
DriveBase1.settings(straight_speed=700)
DriveBase1.straight(1000)
attachment.run_angle(500, 360)
